// Warning: module AI refectored
//! Single source of truth for every file path of the game.
//!
//! The relative layout is the same in embedded and network modes. Only the [`Roots`] (and the
//! optional [`Remote`]) differ:
//!
//! ```text
//! <mods>/<mod_dir>/…                              source mod (sprites, sounds, …)
//! <worlds>/<world_dir>/…                          source world (terrain.png, *.tsx, …)
//! <worlds>/<world_dir>/minimap.png                generated by the `world` command (in archive)
//! <worlds>/<world_dir>/hud_minimap.png
//! <derived>/mods/<mod_id>/soldiers_outline.png    generated by server
//! <derived>/worlds/<world_id>/region_<w>_<h>_<i>.png
//! <derived>/worlds/<world_id>/interior_<id>.png
//! <archives>/{mods,worlds}/<id>.tar.gz            served by server, downloaded by clients
//! ```
//!
//! `mod_dir`/`world_dir` are the directory names under their root: the plain names for in-place
//! (embedded, server) sources and the canonical ids for downloaded (network client) ones.
//!
//! Bevy loads `mods`, `worlds` and `derived` through named asset sources (see
//! [`Roots::asset_sources`] and [`Files::asset`]).

use std::{
    fmt::Display,
    net::SocketAddr,
    path::{Path, PathBuf},
};

#[derive(Debug, Copy, Clone, PartialEq, Eq)]
pub enum File {
    ModArchive,
    WorldArchive,
    Minimap,
    HudMinimap,
    IndividualOutline,
    Region { index: u64, width: u64, height: u64 },
    Interior(u32),
}

/// Directories of the layout. Always absolute.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Roots {
    pub mods: PathBuf,
    pub worlds: PathBuf,
    pub derived: PathBuf,
    pub archives: PathBuf,
}

#[derive(Debug, Copy, Clone, PartialEq, Eq)]
pub enum Source {
    Mods,
    Worlds,
    Derived,
    Archives,
}

#[derive(Debug, Clone)]
pub enum Connection {
    Network(SocketAddr),
    Embedded,
}

/// Where files can be downloaded from (network client only)
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Remote {
    pub base_url: String,
}

#[derive(Debug, Clone)]
pub enum Sync {
    DirectDownload(String),
    ArchiveDownload(String),
}

#[derive(Debug, Clone)]
pub struct Files {
    roots: Roots,
    mod_dir: String,
    mod_id: String,
    world_dir: String,
    world_id: String,
    remote: Option<Remote>,
}

/// Directory (relative to a [`Source`]) as seen by Bevy: `source://relative/path`
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AssetDir(String);

impl AssetDir {
    pub fn join(&self, name: &str) -> String {
        format!("{}/{name}", self.0.trim_end_matches('/'))
    }
}

impl Display for AssetDir {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl Source {
    /// Bevy asset source name
    pub fn name(&self) -> &'static str {
        match self {
            Source::Mods => "mods",
            Source::Worlds => "worlds",
            Source::Derived => "derived",
            Source::Archives => "archives",
        }
    }
}

impl Display for File {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            File::ModArchive => f.write_str("Mod"),
            File::WorldArchive => f.write_str("World"),
            File::Minimap => f.write_str("Minimap"),
            File::HudMinimap => f.write_str("HudMinimap"),
            File::IndividualOutline => f.write_str("SoldierOutline"),
            File::Region { index, .. } => f.write_str(&format!("Region({index})")),
            File::Interior(i) => f.write_str(&format!("Interior({i})")),
        }
    }
}

impl Display for Sync {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Sync::DirectDownload(path) => f.write_str(&format!("DirectDownload({path})")),
            Sync::ArchiveDownload(path) => f.write_str(&format!("ArchiveDownload({path})")),
        }
    }
}

impl Roots {
    /// Roots from existing (in place) sources and a cache directory holding derived files and archives.
    pub fn in_place(mods: &Path, worlds: &Path, cache: &Path) -> std::io::Result<Self> {
        let cache = std::path::absolute(cache)?;
        Ok(Self {
            mods: std::path::absolute(mods)?,
            worlds: std::path::absolute(worlds)?,
            derived: cache.join("derived"),
            archives: cache.join("archives"),
        })
    }

    /// Roots for a network client: everything lives under one data directory.
    pub fn under(data_dir: &Path) -> std::io::Result<Self> {
        let data_dir = std::path::absolute(data_dir)?;
        Ok(Self {
            mods: data_dir.join("mods"),
            worlds: data_dir.join("worlds"),
            derived: data_dir.join("derived"),
            archives: data_dir.join("archives"),
        })
    }

    /// Default data directory of a network client (user data dir of the platform)
    pub fn default_data_dir() -> PathBuf {
        directories::ProjectDirs::from("", "", "OpenCombat")
            .map(|dirs| dirs.data_dir().to_path_buf())
            .unwrap_or_else(|| PathBuf::from("data"))
    }

    pub fn dir(&self, source: Source) -> &Path {
        match source {
            Source::Mods => &self.mods,
            Source::Worlds => &self.worlds,
            Source::Derived => &self.derived,
            Source::Archives => &self.archives,
        }
    }

    /// Create directories the server writes into
    pub fn ensure_server_dirs(&self) -> std::io::Result<()> {
        for dir in [
            self.derived.join("mods"),
            self.derived.join("worlds"),
            self.archives.join("mods"),
            self.archives.join("worlds"),
        ] {
            std::fs::create_dir_all(dir)?;
        }
        Ok(())
    }

    /// Named Bevy asset sources (name, absolute directory) to register before `AssetPlugin`
    pub fn asset_sources(&self) -> [(&'static str, &Path); 3] {
        [Source::Mods, Source::Worlds, Source::Derived].map(|s| (s.name(), self.dir(s)))
    }
}

impl Default for Roots {
    fn default() -> Self {
        let data_dir = Self::default_data_dir();
        Self::under(&data_dir).unwrap_or_else(|_| Self {
            mods: data_dir.join("mods"),
            worlds: data_dir.join("worlds"),
            derived: data_dir.join("derived"),
            archives: data_dir.join("archives"),
        })
    }
}

impl Files {
    /// Client (or in place source) side: `mod_dir` and `world_dir` are the source directories names.
    pub fn new(
        roots: Roots,
        mod_dir: impl Into<String>,
        mod_id: impl Into<String>,
        world_dir: impl Into<String>,
        world_id: impl Into<String>,
    ) -> Self {
        Self {
            roots,
            mod_dir: mod_dir.into(),
            mod_id: mod_id.into(),
            world_dir: world_dir.into(),
            world_id: world_id.into(),
            remote: None,
        }
    }

    /// Server side: sources are given by the server config, only derived files and archives matter.
    pub fn derived_only(roots: Roots, mod_id: &str, world_id: &str) -> Self {
        Self::new(roots, mod_id, mod_id, world_id, world_id)
    }

    pub fn with_remote(mut self, remote: Option<Remote>) -> Self {
        self.remote = remote;
        self
    }

    pub fn roots(&self) -> &Roots {
        &self.roots
    }

    pub fn is_remote(&self) -> bool {
        self.remote.is_some()
    }

    fn source(&self, file: File) -> Source {
        match file {
            File::ModArchive | File::WorldArchive => Source::Archives,
            File::Minimap | File::HudMinimap => Source::Worlds,
            _ => Source::Derived,
        }
    }

    /// Path of the file relative to its source, always with `/` separators
    fn rel(&self, file: File) -> String {
        match file {
            File::ModArchive => format!("mods/{}.tar.gz", self.mod_id),
            File::WorldArchive => format!("worlds/{}.tar.gz", self.world_id),
            File::Minimap => format!("{}/minimap.png", self.world_dir),
            File::HudMinimap => format!("{}/hud_minimap.png", self.world_dir),
            File::IndividualOutline => format!("mods/{}/soldiers_outline.png", self.mod_id),
            File::Region {
                index,
                width,
                height,
            } => format!(
                "worlds/{}/region_{width}_{height}_{index}.png",
                self.world_id
            ),
            File::Interior(id) => format!("worlds/{}/interior_{id}.png", self.world_id),
        }
    }

    pub fn fs(&self, file: File) -> PathBuf {
        self.roots.dir(self.source(file)).join(self.rel(file))
    }

    pub fn asset(&self, file: File) -> String {
        format!("{}://{}", self.source(file).name(), self.rel(file))
    }

    pub fn mod_dir(&self) -> PathBuf {
        self.roots.mods.join(&self.mod_dir)
    }

    pub fn world_dir(&self) -> PathBuf {
        self.roots.worlds.join(&self.world_dir)
    }

    pub fn mod_asset(&self, rel: &str) -> String {
        format!("mods://{}/{rel}", self.mod_dir)
    }

    pub fn world_asset(&self, rel: &str) -> String {
        format!("worlds://{}/{rel}", self.world_dir)
    }

    pub fn sprites(&self) -> AssetDir {
        AssetDir(self.mod_asset("sprites"))
    }

    pub fn sounds(&self) -> AssetDir {
        AssetDir(self.mod_asset("sounds"))
    }

    pub fn terrain_png(&self) -> String {
        self.world_asset("terrain.png")
    }

    pub fn height_png(&self) -> String {
        self.world_asset("height.png")
    }

    pub fn decor_png(&self) -> String {
        self.world_asset("decor.png")
    }

    pub fn terrain_tsx(&self) -> PathBuf {
        self.world_dir().join("terrain.tsx")
    }

    pub fn decor_tsx(&self) -> PathBuf {
        self.world_dir().join("decor.tsx")
    }

    pub fn sync(&self, file: File) -> Option<(Sync, PathBuf)> {
        let remote = self.remote.as_ref()?;
        let base = &remote.base_url;

        match file {
            File::ModArchive => {
                Some((Sync::ArchiveDownload(format!("{base}/mod")), self.mod_dir()))
            }
            File::WorldArchive => Some((
                Sync::ArchiveDownload(format!("{base}/world")),
                self.world_dir(),
            )),
            // Part of the world archive
            File::Minimap | File::HudMinimap => None,
            File::IndividualOutline => Some((
                Sync::DirectDownload(format!("{base}/soldiers_outline")),
                self.fs(file),
            )),
            File::Region { index, .. } => Some((
                Sync::DirectDownload(format!("{base}/region/{index}")),
                self.fs(file),
            )),
            File::Interior(i) => Some((
                Sync::DirectDownload(format!("{base}/interior/{i}")),
                self.fs(file),
            )),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn roots() -> Roots {
        Roots {
            mods: "/m".into(),
            worlds: "/w".into(),
            derived: "/d".into(),
            archives: "/a".into(),
        }
    }

    #[test]
    fn layout_is_shared_between_modes() {
        let embedded = Files::new(roots(), "std1", "std1_1", "world1", "world1_0");
        let network = Files::new(roots(), "std1_1", "std1_1", "world1_0", "world1_0");

        for f in [File::Interior(3), File::IndividualOutline] {
            assert_eq!(embedded.fs(f), network.fs(f));
        }
        assert_eq!(
            embedded.fs(File::Minimap),
            PathBuf::from("/w/world1/minimap.png")
        );
        assert_eq!(
            embedded.asset(File::HudMinimap),
            "worlds://world1/hud_minimap.png"
        );
        assert_eq!(
            embedded.asset(File::Region {
                index: 2,
                width: 10,
                height: 20
            }),
            "derived://worlds/world1_0/region_10_20_2.png"
        );
    }

    #[test]
    fn sources_depend_on_dir_names() {
        let embedded = Files::new(roots(), "std1", "std1_1", "world1", "world1_0");
        assert_eq!(embedded.mod_dir(), PathBuf::from("/m/std1"));
        assert_eq!(
            embedded.sprites().join("a.png"),
            "mods://std1/sprites/a.png"
        );
        assert_eq!(
            embedded.terrain_tsx(),
            PathBuf::from("/w/world1/terrain.tsx")
        );
        assert_eq!(embedded.terrain_png(), "worlds://world1/terrain.png");
    }

    #[test]
    fn nothing_to_sync_without_remote() {
        let files = Files::new(roots(), "a", "a_1", "b", "b_1");
        assert!(files.sync(File::WorldArchive).is_none());

        let files = files.with_remote(Some(Remote {
            base_url: "http://h:1".into(),
        }));
        let (sync, target) = files.sync(File::WorldArchive).unwrap();
        assert_eq!(sync.to_string(), "ArchiveDownload(http://h:1/world)");
        assert_eq!(target, PathBuf::from("/w/b"));
        assert!(files.sync(File::Minimap).is_none());
    }
}
